let palette = ['#116B90', '#CA2126', '#F9C11F', '#F38842', '#F2F3F3', '#2F3351'];
let shapes = [];
let grid = [];
let gridResolution = 9;
let cellSize;
let drawingArea;
let bgColor = '#2F3351';

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	let x = width / 2;
	let y = height / 2;
	let d = 200;
	drawingArea = width * 1;
	cellSize = drawingArea / gridResolution;
	buildGrid();
	for (let cell of grid) {
		shapes.push(new PairShapeEmitter(cell.x, cell.y, cellSize, cell.orientation));
	}
}

function draw() {
	background(bgColor);
	for (let shape of shapes) {
		shape.run();
	}
}

function buildGrid() {
	let margin = (width - drawingArea) / 2;
	for (let j = 0; j < gridResolution; j++) {
		for (let i = 0; i < gridResolution; i += 2) {
			let x = i * cellSize + (cellSize / 2) + margin;
			let y = j * cellSize + (cellSize / 2) + margin;
			let orientation = (i % 4 === 0) ? 0 : 1;
			grid.push({ x: x, y: y, orientation: orientation });
		}
	}
}


function easeOutCubic(x) {
	return 1 - Math.pow(1 - x, 3);
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

class PairShapeEmitter {
	constructor(x, y, d, orientation) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.orientation = orientation;
		this.timer = 0;
		this.shapes = [];
		this.spawnIntervalFrames = 50;

		this.currentColor = random(palette);
		this.previousColor = undefined;

		this.asdf = random(palette);
	}

	display() {
	}

	update() {
		this.timer++;

		noStroke();
		fill(this.asdf);
		circle(this.x, this.y + this.d / 2, this.d);

		for (let s of this.shapes) {
			s.run();
		}

		for (let i = this.shapes.length - 1; i >= 0; i--) {
			if (this.shapes[i].isDead) this.shapes.splice(i, 1);
		}

		if (this.timer % this.spawnIntervalFrames === 0) {
			while (this.currentColor === this.previousColor) {
				this.currentColor = random(palette);
			}

			if (this.orientation === 0) {
				this.shapes.push(new Shape(this.x + (this.d / 2), this.y, this.d, this.currentColor, -PI / 2, 1));
				this.shapes.push(new Shape(this.x - (this.d / 2), this.y, this.d, this.currentColor, PI / 2, -1));
			} else {
				this.shapes.push(new Shape(this.x + (this.d / 2), this.y, this.d, this.currentColor, -PI / 2, -1));
				this.shapes.push(new Shape(this.x - (this.d / 2), this.y, this.d, this.currentColor, PI / 2, 1));
			}

			this.previousColor = this.currentColor;
		}
	}

	run() {
		this.display();
		this.update();
	}
}

