class Shape {
	constructor(x, y, d, col, angle, scaleX) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.col = col;
		this.angle = angle;
		this.scaleX = scaleX;

		this.timer = -0;
		this.duration = 300;
		this.isDead = false;
		this.progress = 0;
	}

	display() {
		push();
		translate(this.x, this.y);
		rotate(this.angle);
		scale(this.scaleX, 1);

		translate(-this.d, 0);
		stroke(0);
		strokeWeight(width * 0.001);
		noStroke();
		fill(this.col);
		let baseRadius = this.d / 2;
		let centerX = lerp(0, this.d, this.progress);
		let radius = sq(centerX) / (4 * baseRadius);
		let centerY = -baseRadius + radius;
		fill(this.col);
		circle(centerX, centerY, radius * 2);
		pop();
	}

	update() {
		this.timer++;
		if (0 < this.timer && this.timer < this.duration) {
			this.progress = pow(norm(this.timer, 0, this.duration - 1), 0.3);
		}
		if (this.timer > this.duration + 50) {
			this.isDead = true;
		}
	}

	run() {
		this.display();
		this.update();
	}
}

